/**
 * A panel with a chart of one series: vertical bars with captions, or meter rows with a percent. Axes: chart
 * (bars, meters), size (default, compact), tone (default, muted).
 */
import { For, type JSX } from "solid-js";
import { Block, Container, Stack } from "../compose";
import { BarChart } from "../components/bar-chart";
import { EmptyState } from "../components/empty-state";
import { MeterRow } from "../components/meter-row";
import { Panel } from "../components/panel";
import { tpl } from "../utils";
import type { Point } from "./chart-panel.types";

export type ChartPanelProps = {
  id: string;
  title: string;
  text: string;
  series: Point[];
  empty?: string;
  summary: string;
  percent: string;
  chart?: "bars" | "meters";
  size?: "default" | "compact";
  tone?: "default" | "muted";
  landmarkLabel?: string;
};

export function ChartPanel({
  id,
  title,
  text,
  series,
  empty = "",
  summary,
  percent,
  chart = "bars",
  size = "default",
  tone = "default",
  landmarkLabel,
}: ChartPanelProps) {
  return (
    <Block
      tag="section"
      aria-labelledby={(landmarkLabel ? undefined : ((title && id) ? tpl("{0}-t", id) : undefined))}
      data-testid="panel-section"
      aria-label={landmarkLabel}
    >
      <Container class="mx-auto w-full max-w-6xl px-4 py-8" data-slot="container">
        <Panel title={title} description={text} id={id} class={(((tone as string) === "muted") ? "bg-muted" : "")}>
          {((series?.length ?? 0) === 0) ? (
            <EmptyState icon="chart-column" title={empty} />
          ) : ((chart as string) === "bars") ? (
            <BarChart bars={series} label={summary} height={(((size as string) === "compact") ? 96 : 176)} />
          ) : (
            <Stack gap={(((size as string) === "compact") ? "0" : "2")} align="stretch" data-testid="items">
              <For each={series ?? []}>{(s) => (
                <MeterRow label={s.label} value={s.value} caption={tpl(percent, s.value)} />
              )}</For>
            </Stack>
          )}
        </Panel>
      </Container>
    </Block>
  );
}

